DBVersion2ADBVersion2	lda #FDBVersion	sta 7,s	bra ADBInit2	endP*>>>> This segment FDBRCV patch goes in	ROM Rev $00 and in Rev $01<<<<FDBRCV	PROC*********************************************************		               **	 Apple IIgs ADB	               **		               **	       by	               **             Original code by  Peter Baum             **    This RAM patch	by Fern Bachman and	Steve Glass    **		               **       Copyright Apple Computer, Inc. 1985-1987       **                 All Rights Reserved	               **		               ********************************************************** CD.TOOL.EQUATES** The following is the SKI tool code.* It implements calls to the Single-Chip-Microcontroller (uC) using* the SKI protocol.* For more information see the Single-Chip-Microcontroller (uC) ERS &* the SKI TOOL ERS** The following Flags/Variables are used:** STATUSTMP: Used to save pending status data from uC. When	a* command is being sent interrupts are locked out, but* the uC status has	to be read. It is acted on at the* end of the routine.(Status = Abort,Flush,Desktop,etc.)** PENDFLG: Indicates if a command is pending. If a command is* clr=nope Pending then it should be finished before any other* set=pend command can be initiated. If	a pending command is* requested while this flag is set then	the code* returns w/ an error code indicating busy - try again* later. If an immediate command is requested then* the pending command is completed and a flag is set:** RSPNSFLG: Indicates if a pending command was completed during* clr=none a request for an immediate command. The response	from* set=pend the pending command is processed after the immediate* command is done.** RSPNSBUF: Buffer to hold response: 8 bytes for data, 1 for count** The code makes extensive use of the stack and direct page. At* the beginning of most tool functions room is made on the* stack and then the direct page is placed on top of the stack to* allow easy access	to these variables.	In most tool functions the* stack looks like this:** 26-27 Word - Input Parameter* 22-25 Long - Input Parameter* 20-21 Word - Input Parameter* 1D-1F Adrs - Tool	Dispatcher Return address* 1A-1C Adrs - Calling Code Return Address* 18-19 Word - Original Direct Page* 17 Byte - Original Processor Status* 16 Byte - Original Data Bank* 14-15 Word - Variable* A-13 10 - Response Buffer 2* 0-09 10 - Response Buffer 1MYTOOLNUM	EQU $09	;ADB TOOL NUMBERDATAFULL	EQU $20	;DATA REG FULL BIT (IN KEYGLOO STATUS)HARDERR	EQU $0010	;CODE FOR HARD ERRORBUSYERR	EQU $0082	;CODE FOR BUSY ERRORABORTBIT	EQU $40FLUSHBIT	EQU $10RSPNSLNG	EQU 10	;BUFFER FOR PENDING	COMMAND RESPONSEPARMS	EQU RSPNSLNG*2	;USED DURING ENDCALLPHBOFFSET	EQU PARMS+2PHPOFFSET	EQU PHBOFFSET+1PHDOFFSET	EQU PHPOFFSET+1RTLGLU	EQU PHDOFFSET+2	;GLU ROUTINE RETURN	ADDRESSRTLCALL	EQU RTLGLU+3	;CALLING ROUTINE RETURN ADDRESSZPTOS	EQU RTLCALL+3	;OFFSET INTO STACK FOR 1ST DATA BYTEuc_cmd	EQU ZPTOS	;COMMAND TO uCFDBADRS	EQU ZPTOS	;FDB ADDRESSDATAPTR	EQU uc_cmd+2	;POINTER TO DATACPLTVCTR	EQU uc_cmd+2	;COMPLETION VECTOR ADDRESSHOWMANY	EQU DATAPTR+4	;DATA BYTE COUNTRDMEMPTR	EQU DATAPTR+4	;USED TO GET DATAINPTR FOR RDMEM COMMANDMAXCOUNT	EQU DATAPTR+4	;MAXIMUM BUFFER COUNT-USED IN READBYTESFDBCMD	EQU CPLTVCTR+4	;FDB COMMAND BYTE-2ND SENT DURING FDBRCVirq_flush	equ $e1004c	;flush keyboard buffer interrupt vectorirq_micro	equ $e10050	;micro abort interrupt vectorVCTRCPLT	equ $e103dc	;COMPLETION VECTOR ADDRESSSRQTBL	equ $e1154a	;$40 byte table for;  A COMPLETION VECTOR FOR EACH DEVICE & THE FDB ADDRESS/REGISTERFLAGS	equ $e10fd6PENDFLAG	EQU flags	;RAM IN BANK E1RSPNSFLAG	EQU flagsPENDBIT	EQU $0080	;COMMAND PENDINGABSBIT	EQU $0040	;ABSOLUTE DEVICE AUTO-POLLED (16-BIT)RSPNSBIT	EQU $0020	;PENDING COMMAND WAS PROCESSEDSTATUSTMP	equ $e10fd7	;HOLDS ANY PENDING uC STATUS* Keep these variables in this orderSRQNUM	equ $e10fd8	;# OF DEVICES INSTALLED IN SRQ CHAINSRQCNT	equ $e10fd9	;COUNT OF DEVICES POLLED SINCE LAST DATASRQMAX	EQU $10	;MAX OF 16 DEVICES (1-16)SRQPTR	equ $e10fda	;POINTER TO NEXT DEVICE IN SRQ LISTSRQMRU	equ $e10fdb	;MOST RECENTLY USED	DEVICE (TOP OF LIST)ERRCODE	EQU $0911	;CODE FOR SYSTEM DEATH MESSAGE*********************************************************************kbdstrb	equ $c010	;kmstatus	equ $c027	;keymicro status registerdatareg	equ $c026	;keymicro data register;endcall         equ     $ff84c4	 ;peter's special error endcall;errorcall       equ     $ff82b7	 ;another peter's special error endcall;endtool         equ     $ff82af	 ;peter's clean error endcallCMDREG	EQU DATAREG	;KEYGLOO COMMAND REG. (WRITE ONLY)* FDB RECEIVE* This command is very similar to the FDB TALK command except* it uses 2 bytes of command instead of	a single	longa on	longi on	PHD	;SAVE DIRECT PAGE	PHP	;SAVE INTERRUPT STATUS	PHB	;SAVE DATA BANK* INIT sequence for	a typical tool call.* It assumes the following stack structure on entry:* 11-12 Word: Count	of Data bytes (HOWMANY)* D-10 Long: Pointer to Data* B-C Word: Command	to uC* 8-A Adrs: Tool Dispatcher Return* 5-7 Adrs: Calling	Code Return* 3-4 : Original Direct Page* 2 : Processor Status* 1 : Data Bank* TOS->* and adds following:* 2 bytes : Return address from this subroutine* 20 bytes : Buffer	for Response* The direct page is then placed on top	of the stack. The stack is* then pushed down one more byte. This allows the beginning	of the* direct page to be	used as a pointer to data (PHD).* The stack pointer	is not actually moved until the routine	returns* to the tool call.INITOOL		;	longa on	;START IN 16-BIT MODE	longi on	SEI	;DISABLE INTERRUPTS	TSC	;MAKE ROOM IN STACK	FOR BUFFERS	SEC	; (JSR ALREADY TOOK	2 BYTES); JSR no longer taken to get here so SBC operand below is modified by 2 bytes!!!	SBC #RSPNSLNG*2-1+2	;LEAVE ROOM FOR 2 RESPONSE BUFFERS	TCD	;PUT DIRECT PAGE ONTO FUTURE STACK	DEC A	;ADJUST STACK PTR OUTSIDE ZERO PAGE	pea $e1e1	;Changes data bank register to $E1	plb	plb	SEP #$20	;8-BIT ACCUMULATOR	longa off	TCS	;OPENS UP BUFFER INSIDE STACK* Set up Completion	Vector* Assumes 4-byte address in stack* High byte should be zero - lower 3-bytes hold address* If pending command flag already set then flag error busy	LDA CPLTVCTR+3	;GET HI BYTE OF COMPLETION VECTOR	BNE RET1	;ERROR IF NOT 0	LDA #PENDBIT	;CHECK PENDING BIT	TSB |FLAGS	BNE BUSY	;COMMAND ALREADY PENDING - FLAG BUSY	LDY CPLTVCTR	;SAVE OFF LOW WORD OF ADDRESS	STY |VCTRCPLT+1	LDA CPLTVCTR+2	;SAVE OFF HI BYTE OF ADDRESS	STA |VCTRCPLT+3* SEND COMMAND* This routine sends a command to uC & cleans data reg. for	response* If a command is pending then it sets a flag and reads the	response* into a buffer, before executing the immediate command. After* performing the immediate command the response is processed.* After sending the	immediate command the Status Reg. is read* till either the command is read by the uC (reg. empty) OR	Timeout* The data reg. is then read Immediately to clear out any* pending uC status. This guarantees that the next byte written to the* data reg. will not be status, but data in response to a RCV command.* Valid uC status is stored in Statustmp & processed at end	of command* Should always be followed with an ENDIMD call to process any pending* read responses or	status.* 8-bit m, 16-bit x* Error = Carry set	longa off	longi on	LDA uc_cmd	;GET COMMANDCMDSEND	JSR SENDDATA	;AND SEND IT AND WAIT TIL READ	BCS RET1	AND #DATAFULL/2	;CHECK IF DATA REG FULL	BEQ RET1	;NOT FULL	LDA DATAREG	;FULL - GET uC STATUS	TSB |STATUSTMP	;AND SAVERET1		; ;CARRY SET = ERR	BCS ERROR3	LDA FDBCMD	;	JSR SENDDATA	;FOLLOW W/ FDB COMMAND BYTE	BCC ENDTOOL	;CLEAN UP ANY STATUS/RESPONSE LEFTOVERS*		;RESTORE STACK, ETC.error3	LDA #PENDBIT	;SINCE ERROR OCCURRED CLEAR PENDING FLAG	TRB |FLAGS	jsr endimd	;clean up any pending status	ldx #$0008	;clean off 8 input parameters	ldy #harderr	;error code	bra endcallBUSY		;	LDX #$0008	;CLEAN 8 BYTES OF STACK	LDY #BUSYERR	;FLAG BUSY ERROR	BRA ENDCALL* SEND DATA* Send data or command, to the uC using	the command reg.* If command reg. is empty sends a data	byte, otherwise flags error* If data not read w/ 30 ms. then timeout error* Uses: A (8-BIT)* X (16-BIT)* Input: A=Command* Output: A=KMSTATUS* Errors: CARRY SETSENDDATA		;	longa off	longi on	TAX	;SAVE OFF DATA	LDA KMSTATUS	;GET CMD REG FULL BIT -> LSB	ROR A	; INTO CARRY	TXA	;GET DATA BACK	BCS local_var2	;REG. NOT EMPTY SO FLAG ERROR	STA CMDREG	;STORE AWAY NEW COMMAND	LDX #7500	;TIMEOUT 7500*(2+2+4+2+3)/3 = 30 MS.local_var1	DEX	;	BEQ FDBTIMEOUT	LDA KMSTATUS	;GET CMD REG FULL BIT -> LSB	ROR A	; INTO CARRY	BCS local_var1	;SET IF FULL (NOT READ)*		;CLR IF EMPTY (READ)local_var2	RTS	;LEAVE W/ A=KMSTATUS CONTENTSFDBTIMEOUT	sec	rtsendtool	jsr endimd	;clean up any pending status* clean up stack and finish call	ldx #$0008	;clean off 8 input parameters* end routine* used to clean up input parameters off	stack,* restore stack pointer, direct page, &	data bank.* sets up carry for	error.* input: y -> error	code* x=parms -> parameter bytes on stack to be cleaned off	rep #$30	longa on	longi on	ldy #$0000	;indicates no error	bra endallendcall	equ *	rep #$30	;return in 16-bit m,x	tya	ora #mytoolnum*256	;mytool # in hi byte	tayendall	lda rtlglu+4	;move glu routine return address	sta rtlglu+4,x	lda rtlglu+2	sta rtlglu+2,x	; and calling return address	lda rtlglu+0	sta rtlglu+0,x	stx parms	;save # of parameters	tsc	;move stack pointer	to restore status	clc	adc #rspnslng*2+2	;point to saved status (plb,p,d)	tcs	adc parms	;calculate new location of stack pointer	adc #$0004	;by adding offset +	4 (saved status)	tax	;save for now	plb	;restore data bank	plp	; interrupt status	pld	; direct page	tya	;set error code	cmp #$0001	;set carry for error code (clr on 0)	txs	;move new stack pointer	rtl	;return to glu* Routine to process the end of a command* Handles any saved	status conditions such as FLUSH, ABORT,	DESKTOP* Handles the response read from a pending command if it exists* Ignores the Desktop Manager Bit ! This occurs because this code* would have to emulate all the code the interrupt dispatcher* supports before calling the desk manager entry point.** 8-Bit m, 16-bit x*ENDIMD	SEP #$30	;8-BIT m,x	longa off	longi off	LDA #ABORTBIT+FLUSHBIT ;CLEAR OUT LOW 3	BITS, RESPONSE, SRQ	AND |STATUSTMP	; OF STATUS FLAGS	STA |STATUSTMP	;AND UPDATE STATUS FLAGS	BEQ local_labl3	;NO PENDING STATUS CONDITIONS	CMP #ABORTBIT	;IF ONLY ABORT BIT SET->ABORT CONDITION	BNE local_labl1*  PROCESS ABORT	PHB	;SAVE DATA BANK	LDA #0	;SET DATA BANK =0	PHA	PLB	JSL >irq_micro	;PROCESS ABORT - IF	RETURNS THEN OK	PLB	;RESTORE DATA BANKlocal_labl1	LDA |STATUSTMP	;LOOK FOR FLUSH BUFFER BIT	ASL A	ASL A	BEQ local_labl3	;NOT SET	BCC local_labl2	;IF ABORT BIT SET THEN CLEAR KEYBOARD	STA KBDSTRBlocal_labl2	LDA #0	STA |STATUSTMP	;CLEAR OUT THE REST	OF STATUS BITS	PHB	PHA	;SET DATA BANK TO 0	PLB	JSL >irq_flush	;PROCESS FLUSH	PLB	;RESTORE DATA BANKlocal_labl3	LDA #RSPNSBIT	TRB |RSPNSFLAG	;TEST & CLEAR OUT RESPONSE FLAG	BEQ local_labl4	;IF NO RESPONSE THEN DONE* Response was read, from pending command, during immediate	command* Process data by calling completion vector	LDA #PENDBIT	TRB |PENDFLAG	;CLEAR COMMAND PENDING FLAG	BEQ local_labl4	PEA $0000	;SET UP BUFFER ADDRESS ON STACK	PHD	;BOTTOM OF STACK	longa off	longi off	SEP #$30	;8-BIT m,x	JSL >VCTRCPLT	;IF RESPONSE READ PREVIOUSLY-PROCESS NOW	longa on	longi on	REP #$30	;16-BIT m,x	PLA	;CLEAN OFF BUFFER ADDRESS	PLA	; IN 16-BITlocal_labl4		;	longa off	;RESET TO 8-BIT M FROM COMPLETION	longi on	;RESET TO 16-BIT X IF SKIPPED COMPLETION	SEP #$20	;8-BIT M, 16-BIT X	REP #$10	RTS	ENDP	END